package com.example.toastmessage; import android.os.Bundle; import android.view.View; import android.widget.EditText; import android.widget.Toast; import androidx.appcompat.app.AppCompatActivity; public class MainActivity extends AppCompatActivity { EditText etToastMessage; @Override protected void onCreate(Bundle b){super.onCreate(b);setContentView(R.layout.activity_main);etToastMessage=findViewById(R.id.etToastMessage);Toast.makeText(this,"Hello World",Toast.LENGTH_SHORT).show();} public void displayToast(View v){String m=etToastMessage.getText().toString().trim();if(m.isEmpty())m="Hello World";Toast.makeText(this,m,Toast.LENGTH_SHORT).show();}}
